public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    // Collect all files and directories to delete, in a list.
    List<File> toDelete = new ArrayList<>();
    Deque<File> stack = new ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        toDelete.add(current);
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children != null) {
                for (File child : children) {
                    if (child != null) {
                        stack.push(child);
                    }
                }
            }
        }
    }
    // Register a shutdown hook to delete the files in reverse order.
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        for (int i = toDelete.size() - 1; i >= 0; i--) {
            File f = toDelete.get(i);
            if (f.exists()) {
                if (!f.delete()) {
                    // Deletion failed; log the failure or rethrow as unchecked.
                    System.err.println("Failed to delete " + f);
                }
            }
        }
    }));
